  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'soil', 4, $j${"emoji":"🪴","name":{"ha":"Cika da ƙasa","en":"Fill with soil"},"text":{"ha":"Ana cika ta da ƙasa mai kyau.","en":"Fill it with good soil."},"kid":true}$j$::jsonb);
