  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'decorate', 10, $j${"emoji":"🎨","name":{"ha":"Yi ado","en":"Decorate"},"text":{"ha":"Ana yi masa ado da launuka.","en":"Decorate it with colours."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'useIt', 11, $j${"emoji":"✅","name":{"ha":"Fara amfani","en":"Start using it"},"text":{"ha":"Yanzu sabon abun yana aiki!","en":"Your new product is ready to use!"},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'collectCloth', 12, $j${"emoji":"👕","name":{"ha":"Tattara yadi","en":"Collect cloth"},"text":{"ha":"Ana tattara tsohon yadi mai ƙarfi.","en":"Collect strong old cloth."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'washCloth', 13, $j${"emoji":"🧼","name":{"ha":"Wanke yadi","en":"Wash the cloth"},"text":{"ha":"Ana wanke yadin a bar shi ya bushe.","en":"Wash the cloth and let it dry."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cutCloth', 14, $j${"emoji":"✂️","name":{"ha":"Yanka yadi","en":"Cut the cloth"},"text":{"ha":"Babba ne ke yanka yadin da almakashi.","en":"An adult cuts the cloth with scissors."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'sew', 15, $j${"emoji":"🪡","name":{"ha":"Ɗinka","en":"Sew"},"text":{"ha":"Babba yana ɗinke gefuna da allura.","en":"An adult sews the edges with a needle."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'handles', 16, $j${"emoji":"🎒","name":{"ha":"Saka hannaye","en":"Add handles"},"text":{"ha":"Ana saka hannayen jaka.","en":"Add the bag handles."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'collectCan', 17, $j${"emoji":"🥫","name":{"ha":"Tattara gwangwani","en":"Collect a can"},"text":{"ha":"Ana tattara gwangwani mara komai.","en":"Collect an empty tin can."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'washCan', 18, $j${"emoji":"🚿","name":{"ha":"Wanke gwangwani","en":"Wash the can"},"text":{"ha":"Ana wanke gwangwanin da ruwa da sabulu.","en":"Wash the can with soap and water."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'smooth', 19, $j${"emoji":"🧰","name":{"ha":"Kare gefen kaifi","en":"Make the edge safe"},"text":{"ha":"Babba yana goge ko rufe gefen kaifi da tef.","en":"An adult smooths or tapes the sharp edge."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'paint', 20, $j${"emoji":"🖌️","name":{"ha":"Yi fenti","en":"Paint"},"text":{"ha":"Ana yi wa gwangwani fenti mai kyau.","en":"Paint the can with bright colours."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'dryPaint', 21, $j${"emoji":"☀️","name":{"ha":"A bar ya bushe","en":"Let it dry"},"text":{"ha":"Ana barin fentin ya bushe.","en":"Let the paint dry."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bioCollect', 22, $j${"emoji":"🥬","name":{"ha":"Tattara shara ta halitta","en":"Collect organic waste"},"text":{"ha":"Ana tattara ragowar abinci da ganye marasa kyau.","en":"Collect leftover food and plant scraps."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bioMix', 23, $j${"emoji":"🪣","name":{"ha":"Haɗa da ruwa","en":"Mix with water"},"text":{"ha":"Babba yana gauraya shara da ruwa ya zama ruwa mai kauri.","en":"An adult mixes the waste with water into a thick slurry."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bioFill', 24, $j${"emoji":"🛢️","name":{"ha":"Zuba a rufaffen tanki","en":"Fill the sealed tank"},"text":{"ha":"Babba yana zuba gaurayen a cikin rufaffen tanki da ake kira digester.","en":"An adult pours the slurry into a sealed tank called a digester."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bioWork', 25, $j${"emoji":"🦠","name":{"ha":"A bar ƙananan halittu su yi aiki","en":"Let the tiny helpers work"},"text":{"ha":"Babu iska a cikin tankin. Ƙananan halittu suna ruɓar da shara cikin makonni suna fitar da gas.","en":"With no air inside, tiny living things break the waste down over weeks and release gas."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bioStore', 26, $j${"emoji":"🎈","name":{"ha":"A tara gas","en":"Collect the gas"},"text":{"ha":"Gas yana taruwa a saman tankin, sai ya bi bututu zuwa wurin ajiya.","en":"The gas collects at the top of the tank and travels by pipe to storage."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bioCook', 27, $j${"emoji":"🍳","name":{"ha":"A yi girki da gas","en":"Cook with the gas"},"text":{"ha":"Masu fasaha masu horo suna haɗa bututu zuwa murhun gas.","en":"Trained technicians connect the pipe to a gas stove."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'bioSlurry', 28, $j${"emoji":"🌱","name":{"ha":"Ragowar ta zama taki","en":"What is left becomes fertiliser"},"text":{"ha":"Ragowar da ke fita daga tankin taki ne mai kyau ga gona. Manya ne ke ɗebo ta.","en":"What comes out of the tank is good fertiliser for the farm. Adults handle it."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plCollect', 29, $j${"emoji":"🧴","name":{"ha":"Tattara tsofaffin filastik","en":"Collect old plastic"},"text":{"ha":"Ana tattara kwalabe, bokiti da kwanoni na filastik da aka gama amfani da su.","en":"Collect used plastic bottles, buckets and bowls."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plSort', 30, $j${"emoji":"🔢","name":{"ha":"Raba su da nau’i","en":"Sort by type"},"text":{"ha":"Ana raba filastik da nau’insa da launi.","en":"Sort the plastic by type and colour."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plWash', 31, $j${"emoji":"🚿","name":{"ha":"Wanke su","en":"Wash it"},"text":{"ha":"Ana wanke su don cire datti da takardar da aka manna.","en":"Wash off dirt and sticky labels."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plShred', 32, $j${"emoji":"⚙️","name":{"ha":"Niƙa ƙanana","en":"Shred into flakes"},"text":{"ha":"Na’ura tana niƙa filastik ya zama ƙananan guda. Manya ne ke aiki da ita.","en":"A machine shreds the plastic into small flakes. Adults run it."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plMelt', 33, $j${"emoji":"🔥","name":{"ha":"A narka a na’ura","en":"Melt in a machine"},"text":{"ha":"Manya masu horo suna narka su a na’ura, a wuri mai iska da kayan kariya.","en":"Trained adults melt the flakes in a machine, in a ventilated place with protective gear."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plMould', 34, $j${"emoji":"🏭","name":{"ha":"A zuba a cikin ƙira","en":"Shape in a mould"},"text":{"ha":"Ana zuba narkakken filastik a cikin ƙira (abin da ke da siffar kayan da ake so) ya huce ya taurare.","en":"The melted plastic goes into a mould (a form with the shape we want), then cools and hardens."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'plUse', 35, $j${"emoji":"🪣","name":{"ha":"Sabon kayan filastik","en":"A new plastic product"},"text":{"ha":"Yanzu akwai sabon bokiti ko kujera da za a yi amfani da shi!","en":"Now there is a new bucket or chair ready to use!"},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'planter', 0, $j${"id":"planter","emoji":"🪴","name":{"ha":"Tukunyar fure","en":"Flower pot"},"steps":["collectBottle","washBottle","cutBottle","holes","soil","seed"],"result":{"emoji":"🪴","name":{"ha":"Tukunyar fure","en":"Flower pot"}},"summary":{"ha":"Tukunyar fure: ana yanka a huda (manya), sai a cika da ƙasa.","en":"Flower pot: cut and drilled by adults, then filled with soil."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'organiser', 1, $j${"id":"organiser","emoji":"🗂️","name":{"ha":"Mai ajiye kayan rubutu","en":"Desk organiser"},"steps":["collectBox","measure","cutBox","glue","decorate","useIt"],"result":{"emoji":"🗂️","name":{"ha":"Mai ajiye kayan rubutu","en":"Desk organiser"}},"summary":{"ha":"Mai ajiye kaya: ana auna, ana yanka (babba), ana manna, ana ado.","en":"Organiser: measured, cut by an adult, glued and decorated."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'bag', 2, $j${"id":"bag","emoji":"👜","name":{"ha":"Jakar yadi","en":"Cloth bag"},"steps":["collectCloth","washCloth","cutCloth","sew","handles","useIt"],"result":{"emoji":"👜","name":{"ha":"Jakar yadi","en":"Cloth bag"}},"summary":{"ha":"Jakar yadi: ana wanke, ana yanka da ɗinka (manya).","en":"Cloth bag: washed, then cut and sewn by adults."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'holder', 3, $j${"id":"holder","emoji":"✏️","name":{"ha":"Mariƙin alƙalumma","en":"Pencil holder"},"steps":["collectCan","washCan","smooth","paint","dryPaint","useIt"],"result":{"emoji":"✏️","name":{"ha":"Mariƙin alƙalumma","en":"Pencil holder"}},"summary":{"ha":"Mariƙi: babba yana kare gefen kaifi, sai a yi fenti.","en":"Holder: an adult makes the sharp edge safe, then it is painted."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'biogas', 4, $j${"id":"biogas","emoji":"⛽","name":{"ha":"Biogas","en":"Biogas"},"steps":["bioCollect","bioMix","bioFill","bioWork","bioStore","bioCook","bioSlurry"],"result":{"emoji":"🍳","name":{"ha":"Iskar girki da taki","en":"Cooking gas and fertiliser"}},"summary":{"ha":"Biogas: shara ta halitta a rufaffen tanki babu iska, ƙananan halittu su fitar da gas, ragowar ta zama taki. Masu fasaha ne ke ginawa.","en":"Biogas: organic waste in a sealed tank with no air, tiny helpers release gas, and the leftovers become fertiliser. Technicians build it."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'plasticRecycle', 5, $j${"id":"plasticRecycle","emoji":"♻️","name":{"ha":"Sake sarrafa filastik","en":"Plastic recycling"},"steps":["plCollect","plSort","plWash","plShred","plMelt","plMould","plUse"],"result":{"emoji":"🪣","name":{"ha":"Sabon kayan filastik","en":"A new plastic product"}},"summary":{"ha":"Sake sarrafa filastik: a raba, a wanke, a niƙa, manya su narka su a wuri mai iska, a zuba a ƙira.","en":"Plastic recycling: sort, wash, shred, adults melt it in a ventilated place, then shape it in a mould."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🧴","kind":"resource","name":{"ha":"Tsohuwar kwalba","en":"Old bottle"},"why":{"ha":"Kwalba ce da aka gama amfani da ita. Za a iya amfani da ita kuma. Abu na asali ne.","en":"A used bottle can be used again. It is a resource."}},{"emoji":"🪴","kind":"product","name":{"ha":"Tukunyar fure","en":"Flower pot"},"why":{"ha":"An yi ta daga kwalba. Sabon abu ne.","en":"It is made from a bottle. It is a new product."}},{"emoji":"👕","kind":"resource","name":{"ha":"Tsohon yadi","en":"Old cloth"},"why":{"ha":"Yadi ne da za a sake amfani da shi. Abu na asali ne.","en":"Cloth that can be used again. It is a resource."}},{"emoji":"✏️","kind":"product","name":{"ha":"Mariƙin alƙalumma","en":"Pencil holder"},"why":{"ha":"An yi shi daga gwangwani. Sabon abu ne.","en":"It is made from a tin can. It is a new product."}},{"emoji":"🥬","kind":"resource","name":{"ha":"Ragowar abinci da ganye","en":"Food and plant scraps"},"why":{"ha":"Shara ta halitta ce da za a iya sarrafawa. Abu na asali ne.","en":"Organic waste that can be processed. It is a resource."}},{"emoji":"⛽","kind":"product","name":{"ha":"Biogas","en":"Biogas"},"why":{"ha":"Ana yin biogas daga shara ta halitta. Sabon abu ne.","en":"Biogas is made from organic waste. It is a new product."}},{"emoji":"🪣","kind":"product","name":{"ha":"Sabon bokiti na filastik","en":"New plastic bucket"},"why":{"ha":"An yi shi daga tsofaffin filastik da aka narka. Sabon abu ne.","en":"It is made from old plastic that was melted. It is a new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🚿","kind":"safe","name":{"ha":"Wanke kwalba mara komai","en":"Wash an empty bottle"},"why":{"ha":"Wannan lafiya ne, da ruwa da sabulu.","en":"This is safe with soap and water."}},{"emoji":"🎨","kind":"safe","name":{"ha":"Yi wa akwati ado da launuka","en":"Decorate a box with colours"},"why":{"ha":"Ado da launuka lafiya ne.","en":"Decorating with colours is safe."}},{"emoji":"🔪","kind":"adult","name":{"ha":"Yanka kwalba da wuƙa","en":"Cut a bottle with a knife"},"why":{"ha":"Wuƙa tana da kaifi. Babba ne kawai.","en":"Knives are sharp. Only an adult."}},{"emoji":"🥫","kind":"adult","name":{"ha":"Gwangwani mai gefen kaifi","en":"A can with a sharp edge"},"why":{"ha":"Gefen zai iya yanka hannu. Ka kira babba.","en":"The edge can cut your hand. Call an adult."}},{"emoji":"🧪","kind":"adult","name":{"ha":"Kwalbar da aka sa sinadari a ciki","en":"A bottle that held chemicals"},"why":{"ha":"Kada ka taɓa ta. Ka gaya wa babba.","en":"Do not touch it. Tell an adult."}},{"emoji":"🔢","kind":"safe","name":{"ha":"Raba kwalabe masu tsabta da nau’insu","en":"Sort clean bottles by type"},"why":{"ha":"Raba filastik mai tsabta lafiya ne.","en":"Sorting clean plastic is safe."}},{"emoji":"🔥","kind":"adult","name":{"ha":"Narka ko ƙone filastik","en":"Melting or burning plastic"},"why":{"ha":"Hayaƙin yana da guba. Manya masu horo ne kawai a wuri mai kayan kariya.","en":"The smoke is toxic. Only trained adults in a place with protective gear."}},{"emoji":"⛽","kind":"adult","name":{"ha":"Kusantar tankin biogas da wuta","en":"Going near a biogas tank with a flame"},"why":{"ha":"Biogas yana ƙonewa. Ka tsaya nesa ka gaya wa babba.","en":"Biogas can catch fire. Stay away and tell an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Wa ke yanka kwalba da gwangwani?","en":"Who cuts bottles and tin cans?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Babu kowa","en":"Nobody"}]$j$::jsonb, 0, $j${"ha":"Kayan yanka suna da kaifi. Babba ne kawai ke yi.","en":"Cutting tools are sharp. Only an adult does it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wane sabon abu ake yi daga kwalbar filastik?","en":"What new product can we make from a plastic bottle?"}$j$::jsonb, $j$[{"ha":"Jakar yadi","en":"Cloth bag"},{"ha":"Tukunyar fure","en":"Flower pot"},{"ha":"Mariƙin alƙalumma","en":"Pencil holder"}]$j$::jsonb, 1, $j${"ha":"Ana yanka kwalba a huda ƙasa, sai a cika da ƙasa. Ta zama tukunyar fure.","en":"The bottle is cut, drilled and filled with soil. It becomes a flower pot."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Wane ne ake ɗinkawa?","en":"Which one is sewn?"}$j$::jsonb, $j$[{"ha":"Tukunyar fure","en":"Flower pot"},{"ha":"Jakar yadi","en":"Cloth bag"},{"ha":"Mariƙin alƙalumma","en":"Pencil holder"}]$j$::jsonb, 1, $j${"ha":"Ana ɗinke yadi ya zama jaka. Babba ne ke ɗinkawa.","en":"Cloth is sewn into a bag. An adult does the sewing."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Menene “sake amfani”?","en":"What does “reuse” mean?"}$j$::jsonb, $j$[{"ha":"Jefar da abu","en":"Throw a thing away"},{"ha":"Amfani da abu kuma maimakon jefarwa","en":"Use a thing again instead of throwing it away"},{"ha":"Ƙone abu","en":"Burn a thing"}]$j$::jsonb, 1, $j${"ha":"Sake amfani yana nufin amfani da abu sau da yawa.","en":"Reuse means using a thing many times."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Me ya sa ba a ƙone shara?","en":"Why do we not burn waste?"}$j$::jsonb, $j$[{"ha":"Hayaƙin yana cutarwa","en":"The smoke is harmful"},{"ha":"Yana da daɗi","en":"It is fun"},{"ha":"Yana ƙara ƙima","en":"It adds value"}]$j$::jsonb, 0, $j${"ha":"Hayaƙin shara yana cutar da numfashi da muhalli.","en":"Smoke from waste harms breathing and nature."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me ya sa ake huda ƙasan tukunyar fure?","en":"Why do we make holes in the bottom of a flower pot?"}$j$::jsonb, $j$[{"ha":"Don ruwa ya zubo","en":"So water can drain out"},{"ha":"Don ya yi nauyi","en":"To make it heavy"},{"ha":"Don ya yi kyau","en":"To make it pretty"}]$j$::jsonb, 0, $j${"ha":"Ruwa mai yawa yana lalata tushen shuka. Ramuka suna barin ruwa ya zubo.","en":"Too much water harms the roots. Holes let extra water drain."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Me za ka yi da kwalbar da aka sa sinadari a ciki?","en":"What do you do with a bottle that held chemicals?"}$j$::jsonb, $j$[{"ha":"Na bar ta na gaya wa babba","en":"Leave it and tell an adult"},{"ha":"Na buɗe na ji ƙamshi","en":"Open it and smell it"},{"ha":"Na yi amfani da ita","en":"Use it for crafts"}]$j$::jsonb, 0, $j${"ha":"Sinadari yana da haɗari. Kada ka taɓa. Ka gaya wa babba.","en":"Chemicals are dangerous. Do not touch. Tell an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 7, $j${"ha":"Menene biogas?","en":"What is biogas?"}$j$::jsonb, $j$[{"ha":"Ruwan sha","en":"Drinking water"},{"ha":"Gas da ake samu daga shara ta halitta a rufaffen tanki","en":"A gas made from organic waste in a sealed tank"},{"ha":"Ƙasa mai taki","en":"Fertile soil"}]$j$::jsonb, 1, $j${"ha":"Ƙananan halittu suna ruɓar da shara ta halitta babu iska, su fitar da gas. Ana girki da shi.","en":"Tiny living things break down organic waste without air and release a gas. It is used for cooking."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 8, $j${"ha":"Ka ji wari mai ƙarfi kamar ruɓaɓɓen ƙwai kusa da tankin biogas. Me za ka yi?","en":"You smell a strong rotten-egg smell near a biogas tank. What do you do?"}$j$::jsonb, $j$[{"ha":"Na kunna wuta","en":"Light a flame"},{"ha":"Na buɗe tankin","en":"Open the tank"},{"ha":"Na tafi wuri mai iska na gaya wa babba","en":"Move to fresh air and tell an adult"}]$j$::jsonb, 2, $j${"ha":"Gas mai ƙonewa yana da haɗari. Ka nesanta kanka ka gaya wa babba.","en":"A flammable gas is dangerous. Get away and tell an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 9, $j${"ha":"Me ya sa ba a narka ko ƙone filastik a gida?","en":"Why do we never melt or burn plastic at home?"}$j$::jsonb, $j$[{"ha":"Hayaƙinsa yana da guba","en":"Its smoke is toxic"},{"ha":"Yana yin daɗi","en":"It is fun"},{"ha":"Yana ƙara ƙima","en":"It adds value"}]$j$::jsonb, 0, $j${"ha":"Hayaƙin filastik yana cutar da numfashi. Manya masu horo ne kawai a wurin sake sarrafawa mai kayan kariya.","en":"Plastic smoke harms breathing. Only trained adults at a recycling place with protective gear."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🌾","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A makarantarmu akwai lambu. Ganye da bawon kayan lambu sun taru da yawa.","en":"Our school has a garden. Lots of leaves and vegetable peels have piled up."}},{"text":{"ha":"Mai lambu yana son ya ciyar da shuke-shuke. Za ka iya taimaka masa?","en":"The gardener wants to feed the plants. Can you help him?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Shara ta halitta abu na asali ce","en":"Organic waste is a resource"},"lines":[{"text":{"ha":"Ganye da bawon ’ya’yan itace suna fitowa daga tsirrai. Abu na asali ne.","en":"Leaves and fruit peels come from plants. They are a resource."}},{"text":{"ha":"Idan an sarrafa su, sai su zama taki, sabon abu mai amfani.","en":"When we process them, they become compost, a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"🍌","title":{"ha":"Shara ta halitta","en":"Organic waste"},"lines":[{"text":{"ha":"Shara ta halitta tana fitowa daga tsirrai da abinci, kamar ganye, bawon ayaba da ciyawa.","en":"Organic waste comes from plants and food, like leaves, banana peels and grass."}},{"text":{"ha":"Tana ruɓewa a hankali ta koma ƙasa. Wannan abu ne na halitta.","en":"It slowly rots and turns back into soil. That is natural."}},{"text":{"ha":"Kwalba da gwangwani ba sa ruɓewa. Ba shara ta halitta ba ce.","en":"Bottles and cans do not rot. They are not organic waste."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kada ka ci taki ko kayan da suka ruɓe. Ka wanke hannu da sabulu bayan ka taɓa su.","en":"Never eat compost or rotten food. Wash your hands with soap after touching them."}},{"text":{"ha":"Kada ka taɓa kashin dabbobi ko ƙaya. Babba ne kawai ke haƙa ko juya tarin. Wannan wasa ne kawai.","en":"Do not touch animal droppings or thorns. Only an adult digs or turns the pile. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"🍂","title":{"ha":"Tarin taki","en":"Compost heap"},"lines":[{"k":"whatIs","text":{"ha":"Tarin ganye da ragowar kayan lambu da ake bari su ruɓe.","en":"A pile of leaves and plant scraps left to rot."}},{"k":"whatDoes","text":{"ha":"Yana juyewa ya zama taki mai duhu da laushi.","en":"It turns into dark, crumbly compost."}},{"k":"whyNeeded","text":{"ha":"Taki yana ciyar da ƙasa don shuke-shuke su girma.","en":"Compost feeds the soil so plants can grow."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🥬","title":{"ha":"Danye da busasshe","en":"Greens and browns"},"lines":[{"text":{"ha":"Danye: kayan da suke da ɗanshi, kamar bawon kayan lambu da sabuwar ciyawa.","en":"Greens: wet material like vegetable peels and fresh grass."}},{"text":{"ha":"Busasshe: kayan busassu, kamar busasshen ganye da takarda.","en":"Browns: dry material like dry leaves and paper."}},{"text":{"ha":"A haɗa su duka a layi-layi don taki ya yi kyau.","en":"Mix both in layers to make good compost."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🪱","title":{"ha":"Ƙananan masu taimako","en":"Tiny helpers"},"lines":[{"text":{"ha":"Tsutsotsi da ƙananan halittu suna cin ragowar su mayar da su taki.","en":"Worms and tiny living things eat the scraps and turn them into compost."}},{"text":{"ha":"Suna buƙatar iska da ɗanshi kaɗan, kamar soso da aka matse.","en":"They need air and a little moisture, like a squeezed sponge."}},{"text":{"ha":"Shi ya sa ake juya tarin da yayyafa ruwa kaɗan.","en":"That is why we turn the pile and sprinkle a little water."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🚫","title":{"ha":"Abin da ba a saka wa ba","en":"What not to add"},"lines":[{"text":{"ha":"Kada a saka filastik, gilashi, gwangwani ko batir. Ba sa ruɓewa.","en":"Do not add plastic, glass, cans or batteries. They do not rot."}},{"text":{"ha":"Kada a saka nama, ƙashi ko mai. Suna jawo ƙudaje da beraye kuma suna wari.","en":"Do not add meat, bones or oil. They attract flies and rats and smell bad."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Ganye da bawon da aka jefar ba su da amfani, amma taki yana taimaka wa amfanin gona.","en":"Thrown-away leaves and peels earn nothing, but compost helps crops grow."}},{"text":{"ha":"Manomi zai iya adana kuɗin taki ko ya sayar da takin.","en":"A farmer can save money on fertiliser or sell the compost."}},{"text":{"ha":"Kowanne yana da hanyarsa ta sarrafawa. Za ka kalle su duka.","en":"Each one has its own way of being made. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'collectLeaves', 0, $j${"emoji":"🍂","name":{"ha":"Tattara busasshen ganye","en":"Collect dry leaves"},"text":{"ha":"A tattara busasshen ganye daga farfajiya.","en":"Gather dry leaves from the yard."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'sortScraps', 1, $j${"emoji":"🗂️","name":{"ha":"Raba kayan","en":"Sort the scraps"},"text":{"ha":"A raba kayan da suka ruɓe da waɗanda ba sa ruɓewa.","en":"Separate what rots from what does not."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'digBase', 2, $j${"emoji":"⛏️","name":{"ha":"Shirya wuri","en":"Prepare a spot"},"text":{"ha":"Babba yana share wuri a gefen lambu ya yi ƙasa mai laushi.","en":"An adult clears a spot at the edge of the garden and loosens the soil."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'layer', 3, $j${"emoji":"🥬","name":{"ha":"A jera layi-layi","en":"Build in layers"},"text":{"ha":"A shimfiɗa danye da busasshe layi-layi.","en":"Spread greens and browns in layers."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'water', 4, $j${"emoji":"💧","name":{"ha":"A yayyafa ruwa","en":"Sprinkle water"},"text":{"ha":"A yayyafa ruwa kaɗan har ya yi ɗanshi kamar soso da aka matse.","en":"Sprinkle water until it feels like a squeezed sponge."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'turn', 5, $j${"emoji":"🔄","name":{"ha":"A juya tarin","en":"Turn the pile"},"text":{"ha":"Babba yana juya tarin da farfaru don iska ta shiga.","en":"An adult turns the pile with a fork so air can get in."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'wait', 6, $j${"emoji":"⏳","name":{"ha":"A jira ya ruɓe","en":"Wait for it to rot"},"text":{"ha":"Kayan suna ruɓewa a hankali cikin makonni. Taki yana yin duhu kuma yana ƙamshin ƙasa.","en":"The scraps slowly break down over weeks. The compost turns dark and smells like soil."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'useCompost', 7, $j${"emoji":"🌱","name":{"ha":"A yi amfani da shi","en":"Use it"},"text":{"ha":"A shimfiɗa takin a gona don shuke-shuke su girma.","en":"Spread the compost on the garden so plants grow well."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'binHoles', 8, $j${"emoji":"🪣","name":{"ha":"A huda akwati","en":"Drill air holes"},"text":{"ha":"Babba yana huda ƙananan ramuka a akwati don iska ta shiga.","en":"An adult drills small air holes in a bin."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'fillBin', 9, $j${"emoji":"🗑️","name":{"ha":"A cika akwatin","en":"Fill the bin"},"text":{"ha":"A saka danye da busasshe a cikin akwatin layi-layi.","en":"Add greens and browns to the bin in layers."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'cover', 10, $j${"emoji":"🧺","name":{"ha":"A rufe akwatin","en":"Cover the bin"},"text":{"ha":"A rufe akwatin don kada ruwan sama ya yi masa yawa.","en":"Cover the bin so rain does not soak it."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'spreadMulch', 11, $j${"emoji":"🌿","name":{"ha":"A shimfiɗa a kewayen shuka","en":"Spread around plants"},"text":{"ha":"A shimfiɗa ganyen a kusa da shuka don ƙasa ta riƙe ɗanshi.","en":"Spread the leaves around plants so the soil keeps its moisture."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'waterPlant', 12, $j${"emoji":"🚿","name":{"ha":"A shayar da shuka","en":"Water the plants"},"text":{"ha":"A shayar da shuka da ruwa mai tsabta.","en":"Water the plants with clean water."},"kid":true}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'sieveCompost', 13, $j${"emoji":"🧺","name":{"ha":"A tace taki","en":"Sieve the compost"},"text":{"ha":"A tace taki da ya nuna don a cire manyan guda.","en":"Sieve the ripe compost to remove big pieces."},"kid":true}$j$::jsonb);
