  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'gbuild', 4, $j${"emoji":"🔨","name":{"ha":"Gina tare da babba","en":"Build with an adult"},"text":{"ha":"Babba yana yin yanka da huda; yaro yana taimakawa a sauran.","en":"An adult does the cutting and drilling; you help with the rest."}}$j$::jsonb);
