  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"🐔","kind":"resource","name":{"ha":"Kaza","en":"A chicken"},"why":{"ha":"Dabba ce da ake kiwo. Abu na asali ne.","en":"A farm animal. It is a resource."}},{"emoji":"🥚","kind":"product","name":{"ha":"Kwai","en":"Eggs"},"why":{"ha":"Kaza ce ke ba da kwai. Sabon abu ne mai ƙima.","en":"The hen gives eggs. A valuable product."}},{"emoji":"🌾","kind":"resource","name":{"ha":"Abincin kaji","en":"Chicken feed"},"why":{"ha":"Abin da kaji ke ci. Abu na asali ne.","en":"What chickens eat. A resource."}},{"emoji":"🐟","kind":"product","name":{"ha":"Kifi busasshe da aka ƙunsa","en":"Dried, packed fish"},"why":{"ha":"An sarrafa kifi aka ƙunsa. Sabon abu ne.","en":"The fish was processed and packed. A new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🧼","kind":"safe","name":{"ha":"Wanke hannu bayan taɓa kaji","en":"Washing hands after touching chickens"},"why":{"ha":"Wannan lafiya ne kuma yana kare mu.","en":"This is safe and protects us."}},{"emoji":"🌾","kind":"safe","name":{"ha":"Ba kaji abinci tare da babba","en":"Giving chickens feed with an adult"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🤒","kind":"adult","name":{"ha":"Taɓa kaza mara lafiya ko matacciya","en":"Touching a sick or dead bird"},"why":{"ha":"Tana iya yaɗa cuta. Ka gaya wa babba.","en":"It can spread sickness. Tell an adult."}},{"emoji":"💉","kind":"adult","name":{"ha":"Yin allurar rigakafi","en":"Giving a vaccine injection"},"why":{"ha":"Likitan dabbobi ko babba mai horo ne kawai.","en":"Only a vet or trained adult."}},{"emoji":"🍗","kind":"adult","name":{"ha":"Cin kazar da ta mutu da kanta","en":"Eating a bird that died by itself"},"why":{"ha":"Kada ka ci. Ka gaya wa babba.","en":"Never eat it. Tell an adult."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'challenge', 'business', 2, $j${"type":"business","key":"business"}$j$::jsonb);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa muke wanke hannu bayan taɓa kaji?","en":"Why do we wash hands after touching chickens?"}$j$::jsonb, $j$[{"ha":"Kaji na iya ɗauke da ƙwayoyin cuta","en":"Chickens can carry germs"},{"ha":"Don hannu su yi ƙamshi","en":"To make hands smell nice"},{"ha":"Babu dalili","en":"No reason"}]$j$::jsonb, 0, $j${"ha":"Sabulu yana cire ƙwayoyin cuta daga hannu.","en":"Soap removes germs from our hands."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Menene kajin gida ƙanana suka fi buƙata?","en":"What do small chicks need most?"}$j$::jsonb, $j$[{"ha":"Ɗumi, ruwa da abinci","en":"Warmth, water and feed"},{"ha":"Ruwan sama","en":"Rain"},{"ha":"Sanyi","en":"Cold"}]$j$::jsonb, 0, $j${"ha":"Kaji ƙanana ba su iya dumama kansu, suna buƙatar ɗumi, ruwa da abinci.","en":"Chicks cannot keep warm alone: they need warmth, water and feed."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ya sa shimfiɗar gidan kaji take bushewa?","en":"Why must the bedding in the chicken house be dry?"}$j$::jsonb, $j$[{"ha":"Danshi yana kawo cututtuka","en":"Damp brings sickness"},{"ha":"Don ya yi laushi kawai","en":"Only to be soft"},{"ha":"Don ya ɗauki ƙura","en":"To collect dust"}]$j$::jsonb, 0, $j${"ha":"Busasshiyar shimfiɗa tana rage cututtuka.","en":"Dry bedding means less sickness."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me zai faru idan aka ba kifi abinci da yawa?","en":"What happens if fish get too much feed?"}$j$::jsonb, $j$[{"ha":"Ragowar abinci yana ƙazanta ruwa","en":"Leftover feed dirties the water"},{"ha":"Kifi su zama masu haske","en":"Fish glow"},{"ha":"Babu komai","en":"Nothing"}]$j$::jsonb, 0, $j${"ha":"Abinci kaɗan-kaɗan yana kiyaye ruwa mai tsabta.","en":"A little feed at a time keeps the water clean."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Wa ke yin allurar rigakafi?","en":"Who gives vaccine injections?"}$j$::jsonb, $j$[{"ha":"Likitan dabbobi ko babba mai horo","en":"A vet or trained adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Allura tana buƙatar ilimi da tsabta. Manya masu horo ne kawai.","en":"Injections need training and cleanliness. Only trained adults."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me za ka yi idan ka ga kaza mara lafiya?","en":"What do you do if you see a sick bird?"}$j$::jsonb, $j$[{"ha":"Na gaya wa babba","en":"Tell an adult"},{"ha":"Na ɗauke ta da hannu","en":"Pick it up"},{"ha":"Na ci ta","en":"Eat it"}]$j$::jsonb, 0, $j${"ha":"Kaza mara lafiya tana iya yaɗa cuta. Ka bar ta ka gaya wa babba.","en":"A sick bird can spread sickness. Leave it and tell an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"👩🏾‍🍳","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"A kasuwa, lemo da abarba suna lalacewa da sauri. Wata mata tana son yin lemo ta sayar.","en":"At the market oranges and pineapples spoil fast. A woman wants to make drinks to sell."}},{"text":{"ha":"Za ka iya koyon yadda ake yi cikin tsabta?","en":"Can you learn how to do it cleanly?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Lemo, abarba, zobo, aya da ruwa abubuwa ne na asali.","en":"Oranges, pineapples, zobo, tigernuts and water are resources."}},{"text":{"ha":"Idan an wanke, an sarrafa, an tace aka saka a kwalba mai tsabta, sai a samu lemo da za a sayar.","en":"When washed, processed, strained and bottled cleanly they become drinks to sell."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Tsabta ita ce abu mafi muhimmanci: a wanke hannu, ’ya’yan itace da kwalba. Ruwan zafi, wuƙa da blender na manya ne kawai.","en":"Cleanliness comes first: wash hands, fruit and bottles. Hot water, knives and blenders are for adults only."}},{"text":{"ha":"Kada a sha lemo mai wari ko kumfa: a zubar. A ajiye shi a sanyi. Wannan wasa ne kawai.","en":"Never drink juice that smells sour or foams: throw it away. Keep drinks cold. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🍊","title":{"ha":"’Ya’yan itace","en":"Fruit"},"lines":[{"k":"whatIs","text":{"ha":"Lemo, abarba, kankana ko zobo.","en":"Oranges, pineapple, watermelon or zobo."}},{"k":"whatDoes","text":{"ha":"Suna ba da ɗanɗano, ruwa da bitamin.","en":"They give taste, water and vitamins."}},{"k":"whyNeeded","text":{"ha":"Suna lalacewa da sauri. Sarrafawa yana adana su.","en":"They spoil quickly. Processing saves them."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"💧","title":{"ha":"Ruwa mai tsabta","en":"Clean water"},"lines":[{"k":"whatIs","text":{"ha":"Ruwa mai tsabta, wanda aka tafasa idan ana buƙata.","en":"Clean water, boiled when needed."}},{"k":"whatDoes","text":{"ha":"Yana wanke ’ya’yan itace yana haɗa lemo.","en":"It washes the fruit and makes the drink."}},{"k":"whyNeeded","text":{"ha":"Ruwa maras tsabta yana kawo cututtuka.","en":"Dirty water brings sickness."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🍯","title":{"ha":"Ɗanɗano","en":"Sweetness and flavour"},"lines":[{"k":"whatIs","text":{"ha":"Sukari, zuma, dabino ko ɗan kayan ƙamshi.","en":"Sugar, honey, dates or a little spice."}},{"k":"whatDoes","text":{"ha":"Yana ƙara daɗi.","en":"It adds taste."}},{"k":"whyNeeded","text":{"ha":"Amma kada a saka da yawa, domin lafiya.","en":"But not too much, for health."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"🍾","title":{"ha":"Kwalba mai tsabta","en":"Clean bottle"},"lines":[{"k":"whatIs","text":{"ha":"Kwalba mai murfi da aka wanke.","en":"A washed bottle with a lid."}},{"k":"whatDoes","text":{"ha":"Tana adana lemo tana kare shi daga ƙura.","en":"It keeps the drink and protects it from dust."}},{"k":"whyNeeded","text":{"ha":"Kwalba maras tsabta tana lalata lemo.","en":"A dirty bottle spoils the drink."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🧊","title":{"ha":"Sanyi","en":"Keeping it cold"},"lines":[{"k":"whatIs","text":{"ha":"Firji ko kankara.","en":"A fridge or ice."}},{"k":"whatDoes","text":{"ha":"Yana rage lalacewa.","en":"It slows spoiling."}},{"k":"whyNeeded","text":{"ha":"Lemo a rana yana lalacewa da sauri.","en":"Juice in the sun spoils fast."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Lemo da aka yi cikin tsabta ana sayar da shi fiye da ’ya’yan itace danye.","en":"Clean juice sells for more than raw fruit."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
