  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🧼","kind":"safe","name":{"ha":"Wanke hannu da ’ya’yan itace","en":"Washing hands and fruit"},"why":{"ha":"Wannan lafiya ne kuma yana da muhimmanci.","en":"This is safe and very important."}},{"emoji":"🍾","kind":"safe","name":{"ha":"Zuba lemo mai sanyi a kwalba mai tsabta (babba yana kusa)","en":"Pouring cool juice into a clean bottle (adult nearby)"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"♨️","kind":"adult","name":{"ha":"Tafasa ko zuba ruwan zafi","en":"Boiling or pouring hot water"},"why":{"ha":"Zafi yana ƙonewa. Babba ne kawai.","en":"Heat burns. Only an adult."}},{"emoji":"🌀","kind":"adult","name":{"ha":"Amfani da blender ko wuƙa","en":"Using a blender or a knife"},"why":{"ha":"Suna da kaifi. Babba ne kawai.","en":"They are sharp. Only an adult."}},{"emoji":"🤢","kind":"adult","name":{"ha":"Shan lemo mai wari ko kumfa","en":"Drinking juice that smells sour or foams"},"why":{"ha":"Kada ka sha. Ka gaya wa babba.","en":"Never drink it. Tell an adult."}}]}$j$::jsonb);
