  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa tsabta take da muhimmanci a yin lemo?","en":"Why is cleanliness so important when making drinks?"}$j$::jsonb, $j$[{"ha":"Datti yana kawo cututtuka","en":"Dirt brings sickness"},{"ha":"Don lemo ya yi tsada","en":"To make it expensive"},{"ha":"Babu dalili","en":"No reason"}]$j$::jsonb, 0, $j${"ha":"Hannu, ’ya’yan itace da kwalba maras tsabta suna lalata lemo suna sa mutane rashin lafiya.","en":"Dirty hands, fruit and bottles spoil drinks and make people ill."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wa ke tafasa zobo?","en":"Who boils the zobo?"}$j$::jsonb, $j$[{"ha":"Babba","en":"An adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Ruwan zafi yana ƙonewa. Babba ne kawai.","en":"Hot water burns. Only an adult."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me za ka yi da lemo mai wari ko kumfa?","en":"What do you do with juice that smells sour or foams?"}$j$::jsonb, $j$[{"ha":"A zubar a gaya wa babba","en":"Throw it away and tell an adult"},{"ha":"A sha shi","en":"Drink it"},{"ha":"A sayar da shi","en":"Sell it"}]$j$::jsonb, 0, $j${"ha":"Lemo ya lalace idan yana wari ko kumfa. Kada a sha.","en":"Juice that smells sour or foams has spoiled. Never drink it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Me ya sa ake ajiye lemo a sanyi?","en":"Why do we keep drinks cold?"}$j$::jsonb, $j$[{"ha":"Sanyi yana rage lalacewa","en":"Cold slows spoiling"},{"ha":"Don ya yi nauyi","en":"To make it heavy"},{"ha":"Don ya canza launi","en":"To change colour"}]$j$::jsonb, 0, $j${"ha":"A rana lemo yana lalacewa da sauri.","en":"In the sun juice spoils fast."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Menene zobo?","en":"What is zobo?"}$j$::jsonb, $j$[{"ha":"Abin sha daga busasshen furen zobo","en":"A drink from dried zobo flowers"},{"ha":"Wani nau’in bulo","en":"A type of block"},{"ha":"Wani keke","en":"A bicycle"}]$j$::jsonb, 0, $j${"ha":"Ana tafasa busasshen zobo a tace a sha da sanyi.","en":"Dried zobo is boiled, strained and drunk cold."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Me ya sa muke tace lemo?","en":"Why do we strain juice?"}$j$::jsonb, $j$[{"ha":"Don ya yi laushi ba tare da ƙuraje ba","en":"To make it smooth without bits"},{"ha":"Don ya ƙara tsami","en":"To make it sour"},{"ha":"Don a rage shi","en":"To make less of it"}]$j$::jsonb, 0, $j${"ha":"Tacewa tana cire ƙuraje da bawo.","en":"Straining removes bits and pulp."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
