  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'sort', 0, $j${"type":"sort","key":"sort","items":[{"emoji":"⛰️","kind":"resource","name":{"ha":"Yumɓu","en":"Clay"},"why":{"ha":"Yana fitowa daga ƙasa. Abu na asali ne.","en":"It comes from the earth. A resource."}},{"emoji":"🏺","kind":"product","name":{"ha":"Tukunya","en":"A pot"},"why":{"ha":"An ƙera ta daga yumɓu. Sabon abu ne.","en":"It is shaped from clay. A new product."}},{"emoji":"💧","kind":"resource","name":{"ha":"Ruwa","en":"Water"},"why":{"ha":"Ruwa yana fitowa daga yanayi. Abu na asali ne.","en":"Water comes from nature. A resource."}},{"emoji":"🍶","kind":"product","name":{"ha":"Kwano ko kofin yumɓu","en":"A clay bowl or cup"},"why":{"ha":"An ƙera shi daga yumɓu. Sabon abu ne.","en":"It is shaped from clay. A new product."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'challenge', 'drag_drop', 'safety', 1, $j${"type":"safety","key":"safety","items":[{"emoji":"🧼","kind":"safe","name":{"ha":"Wanke hannu bayan aiki da yumɓu","en":"Washing hands after clay work"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🏺","kind":"safe","name":{"ha":"Ƙera ƙaramar tukunya da igiyoyin yumɓu","en":"Shaping a small coil pot"},"why":{"ha":"Wannan lafiya ne.","en":"This is safe."}},{"emoji":"🔥","kind":"adult","name":{"ha":"Kunna wuta ko murhun ƙona tukunya","en":"Lighting the kiln or fire"},"why":{"ha":"Zafi yana ƙonewa. Babba ne kawai.","en":"Heat burns. Only an adult."}},{"emoji":"🥵","kind":"adult","name":{"ha":"Taɓa tukunya da aka ƙona kuma ba ta huce ba","en":"Touching a fired pot that is not cool"},"why":{"ha":"Kada ka taɓa. Jira babba.","en":"Do not touch. Wait for an adult."}},{"emoji":"🧹","kind":"adult","name":{"ha":"Share ƙurar yumɓu busasshe","en":"Sweeping dry clay dust"},"why":{"ha":"Ƙurar tana cutar da huhu. Babba ne zai goge da rigar jiƙa.","en":"The dust harms lungs. An adult wipes it with a damp cloth."}}]}$j$::jsonb);
