  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa ake busar da tukunya a hankali a inuwa?","en":"Why do we dry a pot slowly in the shade?"}$j$::jsonb, $j$[{"ha":"Don kada ta tsage ko ta fashe","en":"So it does not crack or burst"},{"ha":"Don ta yi nauyi","en":"To make it heavy"},{"ha":"Don ta yi sanyi","en":"To make it cold"}]$j$::jsonb, 0, $j${"ha":"Idan ta bushe da sauri ko ba ta bushe ba, za ta fashe a wuta.","en":"If dried too fast, or not dry, it cracks in the fire."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 1, $j${"ha":"Wa ke ƙona tukunya?","en":"Who fires the pot?"}$j$::jsonb, $j$[{"ha":"Babba mai ƙwarewa","en":"An experienced adult"},{"ha":"Yaro shi kaɗai","en":"A child alone"},{"ha":"Kowa","en":"Anyone"}]$j$::jsonb, 0, $j${"ha":"Wuta tana ƙonewa. Manya ne kawai.","en":"Fire burns. Only adults."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Me ya sa muke murɗa yumɓu?","en":"Why do we knead the clay?"}$j$::jsonb, $j$[{"ha":"Don fitar da iska a ciki","en":"To push out air"},{"ha":"Don ya yi sanyi","en":"To cool it"},{"ha":"Don ya canza launi","en":"To change its colour"}]$j$::jsonb, 0, $j${"ha":"Iska a cikin yumɓu na iya sa tukunya ta fashe.","en":"Air in the clay can make a pot burst."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 3, $j${"ha":"Yaya ake goge ƙurar yumɓu busasshe?","en":"How do we clean up dry clay dust?"}$j$::jsonb, $j$[{"ha":"Da rigar da aka jiƙa","en":"With a damp cloth"},{"ha":"A share busasshe","en":"Sweep it dry"},{"ha":"A hura ta","en":"Blow it away"}]$j$::jsonb, 0, $j${"ha":"Ƙurar busasshe tana cutar da huhu. Rigar jiƙa tana kama ta.","en":"Dry dust harms the lungs. A damp cloth catches it."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 4, $j${"ha":"Me zai faru idan ba a ƙona tukunya ba?","en":"What happens if a pot is never fired?"}$j$::jsonb, $j$[{"ha":"Za ta narke a ruwa","en":"It melts in water"},{"ha":"Za ta fi ƙarfi","en":"It is stronger"},{"ha":"Babu komai","en":"Nothing"}]$j$::jsonb, 0, $j${"ha":"Ƙonawa ne ke mai da yumɓu ƙarfi kamar dutse.","en":"Firing is what turns clay hard like stone."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 5, $j${"ha":"Wane ne sabon abu daga yumɓu?","en":"Which is a new product made from clay?"}$j$::jsonb, $j$[{"ha":"Tukunya","en":"A pot"},{"ha":"Ruwa","en":"Water"},{"ha":"Ƙasa","en":"Soil"}]$j$::jsonb, 0, $j${"ha":"Ana ƙera yumɓu ya zama tukunya.","en":"Clay is shaped into a pot."}$j$::jsonb, 5);
  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 6, $j${"ha":"Yaya ake samun riba?","en":"How do we find profit?"}$j$::jsonb, $j$[{"ha":"Farashin sayarwa − kuɗin da aka kashe","en":"Selling price − money spent"},{"ha":"Farashin sayarwa + kuɗin da aka kashe","en":"Selling price + money spent"},{"ha":"Kuɗin ƙunshewa kaɗai","en":"Packaging cost only"}]$j$::jsonb, 0, $j${"ha":"Riba = farashin sayarwa − jimillar kuɗin da aka kashe.","en":"Profit = selling price − total money spent."}$j$::jsonb, 5);
    insert into public.missions (slug, mission_no, emoji, title, category_id, stages, reward_rules, engine_options, status)
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'story', null, 0, $j${"emoji":"🧑🏾‍🔧","title":{"ha":"Sannu, ƙaramin mai ƙirƙira! 👋","en":"Hello, young inventor! 👋"},"lines":[{"text":{"ha":"Keken wani yaro ya huda a hanyar makaranta. Mai gyaran keke zai koya mana yadda ake gyara.","en":"A boy’s bicycle got a puncture on the way to school. A bicycle repairer will teach us how to fix it."}},{"text":{"ha":"Za ka iya koyo ka taimaka?","en":"Can you learn and help?"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Gyara yana ƙara ƙima","en":"Repair adds value"},"lines":[{"text":{"ha":"Keke da ya lalace ba shi da amfani. Bayan gyara, ya zama keke mai aiki.","en":"A broken bike is no use. After repair it works again."}},{"text":{"ha":"Keke mai lalacewa → Gyara → Keke mai aiki → Amfani","en":"Broken bike → Repair → Working bike → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Kayan gyara suna iya matse ko yanke yatsa. Manya ne ke amfani da su da mai da sarƙa. Kada a gwada keke a kan babbar hanya.","en":"Repair tools can pinch or cut fingers. Only adults use them, and oil and the chain. Never test a bike on a main road."}},{"text":{"ha":"Ka sa takalmi, ka tsaya nesa da sarƙa mai juyawa. Ka sa hular kwano idan za ka hau keke. Wannan wasa ne kawai.","en":"Wear shoes and keep clear of a moving chain. Wear a helmet when you ride. This is a game only."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 3, $j${"emoji":"🛞","title":{"ha":"Ƙafa da tayar roba","en":"Wheel and tyre"},"lines":[{"k":"whatIs","text":{"ha":"Ƙafa da tayar roba mai iska a ciki.","en":"A wheel with a rubber tyre holding air."}},{"k":"whatDoes","text":{"ha":"Suna ɗaukar keke su juya.","en":"They carry the bike and roll."}},{"k":"whyNeeded","text":{"ha":"Idan iska ta ragu, keke yana yin nauyi.","en":"When air runs low the bike feels heavy."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 4, $j${"emoji":"⛓️","title":{"ha":"Sarƙa da feda","en":"Chain and pedals"},"lines":[{"k":"whatIs","text":{"ha":"Sarƙa tana haɗa feda da ƙafar baya.","en":"The chain joins the pedals to the back wheel."}},{"k":"whatDoes","text":{"ha":"Idan ka taka feda, sarƙa tana juya ƙafa.","en":"When you push the pedal the chain turns the wheel."}},{"k":"whyNeeded","text":{"ha":"Sarƙa mai mai da ƙarfi tana sauƙaƙa hawa.","en":"A oiled, well-fitted chain makes riding easy."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 5, $j${"emoji":"🛑","title":{"ha":"Birki","en":"Brakes"},"lines":[{"k":"whatIs","text":{"ha":"Roba da ke danne ƙafa.","en":"Rubber pads that squeeze the wheel."}},{"k":"whatDoes","text":{"ha":"Idan ka matse hannun birki, keke yana tsayawa.","en":"When you squeeze the lever the bike stops."}},{"k":"whyNeeded","text":{"ha":"Birki mai kyau yana kare rai.","en":"Good brakes save lives."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 6, $j${"emoji":"💨","title":{"ha":"Famfo da patch","en":"Pump and patch kit"},"lines":[{"k":"whatIs","text":{"ha":"Famfo da kayan manne rami.","en":"A pump and a puncture patch kit."}},{"k":"whatDoes","text":{"ha":"Famfo yana cika iska; patch yana rufe rami.","en":"The pump fills air; the patch seals the hole."}},{"k":"whyNeeded","text":{"ha":"Yana ceton kuɗin sabon tube.","en":"It saves the cost of a new tube."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 7, $j${"emoji":"🔩","title":{"ha":"Mai da maƙulli","en":"Oil and spanner"},"lines":[{"k":"whatIs","text":{"ha":"Mai yana sa sassa su juya santsi; maƙulli yana matse ƙusoshi.","en":"Oil lets parts move smoothly; a spanner tightens nuts."}},{"k":"whatDoes","text":{"ha":"Suna kula da sassan keke.","en":"They look after the bike parts."}},{"k":"whyNeeded","text":{"ha":"Kula da keke yana sa shi ya daɗe.","en":"Care makes a bike last."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 8, $j${"emoji":"💰","title":{"ha":"Sarrafawa yana ƙara ƙima","en":"Processing adds value"},"lines":[{"text":{"ha":"Mai gyaran keke yana samun kuɗi a kowane gyara, kuma yana taimaka wa mutane.","en":"A bicycle repairer earns from every repair and helps people."}},{"text":{"ha":"Kowanne yana da hanyarsa. Wasu matakai na manya ne kawai. Za ka kalle su duka.","en":"Each has its own way. Some steps are for adults only. You will watch them all."}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'uwheel', 0, $j${"emoji":"🔧","name":{"ha":"Cire ƙafa","en":"Take off the wheel"},"text":{"ha":"Babba yana cire ƙafa daga keke.","en":"An adult takes the wheel off the bike."}}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'demo', 'demonstration', 'utyre', 1, $j${"emoji":"🛠️","name":{"ha":"Cire tayar da tube","en":"Take out the tube"},"text":{"ha":"Babba yana cire tayar da kayan cirewa ya fitar da tube.","en":"An adult uses tyre levers to take out the inner tube."}}$j$::jsonb);
