  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'procedure', 'demonstration', 'puncture', 0, $j${"id":"puncture","emoji":"🫧","name":{"ha":"Gyaran huda","en":"Fix a puncture"},"steps":["uwheel","utyre","ufind","upatch","ucheck","upump"],"summary":{"ha":"Huda: cire ƙafa, nemo rami da ruwa, manna patch, duba tayar, cika iska.","en":"Puncture: wheel off, find the hole with water, patch, check the tyre, pump up."},"result":{"emoji":"🚲","name":{"ha":"Keke mai aiki","en":"A working bike"}}}$j$::jsonb);
