  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 0, $j${"ha":"Me ya sa ba a girki da gawayi a cikin ɗaki?","en":"Why do we never cook with charcoal inside a room?"}$j$::jsonb, $j$[{"ha":"Hayaƙinsa (carbon monoxide) yana kashe mutum","en":"Its fumes (carbon monoxide) can kill"},{"ha":"Yana ɗaukar sarari","en":"It takes space"},{"ha":"Yana da nauyi","en":"It is heavy"}]$j$::jsonb, 0, $j${"ha":"Carbon monoxide ba shi da ƙamshi amma yana kashewa. Ana girki a waje ko wuri mai iska.","en":"Carbon monoxide has no smell but kills. Cook outdoors or where air flows."}$j$::jsonb, 5);
