  insert into public.game_questions (mission_id, position, question, options, correct_index, explanation, points) values (v_id, 2, $j${"ha":"Menene aikin manne (sitaci)?","en":"What does the binder (starch) do?"}$j$::jsonb, $j$[{"ha":"Yana manna ƙurar gawayi wuri ɗaya","en":"It sticks the charcoal dust together"},{"ha":"Yana ƙara hayaƙi","en":"It adds smoke"},{"ha":"Yana sa gawayi ya narke","en":"It melts the charcoal"}]$j$::jsonb, 0, $j${"ha":"Ba tare da manne ba gawayin ƙwallo zai farfashe.","en":"Without a binder the briquette would crumble."}$j$::jsonb, 5);
