  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 1, $j${"emoji":"🌍","title":{"ha":"Abu na asali da sabon abu","en":"Resource and new product"},"lines":[{"text":{"ha":"Yadi, zare da allura abubuwa na asali ne.","en":"Cloth, thread and needles are resources."}},{"text":{"ha":"Idan an auna, an yanka an ɗinka, sai a samu riga ko jaka: sabon abu mai amfani.","en":"When measured, cut and sewn they become a shirt or a bag: a useful new product."}},{"text":{"ha":"Abu na asali → Sarrafawa → Sabon abu → Amfani","en":"Resource → Processing → New product → Value"}}]}$j$::jsonb);
  insert into public.mission_steps (mission_id, stage, step_type, step_key, position, content) values (v_id, 'teach', 'explanation', null, 2, $j${"emoji":"⚠️","warn":true,"title":{"ha":"Tsaro","en":"Safety"},"lines":[{"text":{"ha":"Allura, fil da almakashi suna da kaifi. Yara su yi amfani da allura mara kaifi da kulawar babba. Almakashi da wuƙa na manya ne.","en":"Needles, pins and scissors are sharp. Children use a blunt needle with an adult nearby. Scissors and knives are for adults."}},{"text":{"ha":"Injin ɗinki da maƙo (iron) na manya ne kawai. Kada ka saka yatsa kusa da allurar injin. Wannan wasa ne kawai.","en":"Sewing machines and irons are for adults only. Never put fingers near the machine needle. This is a game only."}}]}$j$::jsonb);
